  "。上一阶段编辑结果已由客户端记录，请检查当前 context 与实际就绪素材，完成剩余要求。不要重复已完成的新增卡片或已应用操作。需要分阶段执行时只提交下一批；全部完成后简要说明并且不输出指令。剩余阶段": ". The results of the previous phase of editing are recorded by the client, please check the current context and actual material to complete the remaining requirements. Do not duplicate the new cards that have been completed or the operations that have been applied. Only the next batch needs to be submitted in stages of implementation. A brief description of all completions and no output of the commands is available.",
