  "两侧共用动作、时刻与视图。拖动画布同步平移，点击表面检查该处误差；查看遮挡时关闭网格和热力图。热力图按动画误差阈值着色，低于 0.0002 px 按浮点噪声显示为蓝色。最大值来自检查采样，包含原顶点与交叉边；颜色为表面细分近似。预览人物骨骼、权重、FFD 与遮挡，不包含整卡翻转、材质及自定义着色器。": "Both sides share action, time and view. Drag the canvas to synchronize the move and click on the surface to check the error. Close the grid and thermal effort when looking at the mask. The heat tries to colour by the animation error threshold below 0.0002 px and displays it as blue by floating noise. The maximum value comes from checking the sample, containing the original vertex and the intersection. Colours are subdivided to approximate the surface. Previewing the bones, weights, FFDs and masks of the person, does not contain the whole card flipping, the material, and the custom colourer.",
