  "先选中高误差区，再加密或保护，最后重新减面。修正会恢复当前比较组的源网格、权重与 FFD，保留原关键点；新增支撑点自动保护。每次最多增加 128 点。选区绑定源 UV，随动作运动；其他图层保留，可撤销。": "Select a high-error region. Refine it or protect it, then run simplification again. Repair restores the source mesh, weights, and FFD for this comparison group and protects any new support vertices. Add up to 128 vertices at a time. The selection follows the source UVs during playback. You can undo the repair.",
