  "刚性部件不能使用衣料摆动": "The rigid parts can't be swinged with clothing",
  "刚性部件整体保持平面，不使用连接渐变或衣料摆动；关节接缝需真实重叠补绘，并检查四向倾斜。": "Rigid parts are kept flat as a whole, with no connection gradients or clothing swings. The joints need to be filled with real overlaps, and a four-way tilt is checked.",
  "刚性部件深度": "Rigid Widget Depth",
  "创建区域网格引导": "Create a regional grid guide",
