  "初始化失败：": "Initialization failed:",
  "初始化失败：{0}": "Initialization failed: {0}",
  "初始姿势": "Initial position",
  "初始姿势下调权重通常不会移动图片。使用测试弯曲，查看当前骨骼如何驱动网格；测试姿势只用于预览。": "The lower weight of the initial position does not normally move the picture. The test bends to see how the current bone drives the grid. The test position is used only for preview purposes.",
  "初始绑定": "Initial binding",
  "初始绑定：拖圆点调整关节，拖末端方块调整骨段；这会修改绑定结构，可撤销。": "Initial binding: Drag the dot to adjust the joint and drag the end block to adjust the bone segment. This will modify the binding structure and can be undone.",
  "初绑按骨骼自身骨段距离计算起点权重，需播放极限动作后刷涂修正。每顶点最多 4 骨骼，始终归一化至 100%。手和武器宜保留同一骨骼 100% 权重。": "The starting weight of the bone is based on its own bone segment distance. The maximum of 4 bones per vertex is always integrated to 100%. The same bone weight is maintained for the hand and weapon.",
  "初绑选中顶点": "_Other Organiser",
  "初速度": "First Speed",
  "初速度 {0}": "First speed {0}",
  "初速度从发射源坐标变换；重力和碰撞面使用卡牌／世界空间，法线指向可活动一侧。启用后替代原轨迹参数，外观保留。默认地面高度 -0.6 卡宽。": "The initial velocity changes from the launch source coordinates. Gravity and collisions use card/world space, and the legal line points to the active side. When enabled, replaces the original orbital parameters and maintains the appearance. Default ground height - 0.6 carat width.",
  "删点": "Delete Point",
  "删点、重建会比较前后的初始姿势与全部动作，检查位置、运动、轮廓和权重误差。减面使用累计误差阈值，保留关键点、约束边及剩余点的权重和 FFD；达到误差限制时可能高于目标数量。检查包含关键帧、区间中点和固定采样，不保证任意未来动作。": "Delete points, reconstruct the initial position and all actions, check position, movement, contours and weight error. Declines use cumulative error thresholds that preserve the weight of key points, bound edges and remaining points and the FFD. The error limit may be higher than the target number when reached. The check contains key frames, mid-points and fixed sampling, and does not guarantee any arbitrary future movement.",
  "删除": "Delete",
