  "各英雄、各语言可使用独立透明图片；文字版可在属性中选字体并栅格化。PNG 按原比例放在标题基线，1024 × 1536 的母版保留原位置。缺失语言回退到第一个版本。": "Independent and transparent pictures can be used for heroes and languages. Text versions can be selected and gridd in attributes. PNG is proportionally placed in the title baseline, with the master of 1024 x 1536 remaining in place. Missing language returns to the first version.",
  "合并": "Merge",
