  "合成附图需要制作上下文": "Synthetic attachment requires context",
  "同一动画继续播放；图片按原比例生成，骨架、权重与 FFD 保留。Mask 不降采样。导出整套工坊时，预设应用于全部卡牌；图层规则按卡牌保留。": "The same animation continues to be played. The picture is generated proportionally, the skeleton, weight and fDD are kept. Mask does not drop the sample. When exporting the entire workshop, the whole card is preset for all cards. The layer rules are set for cards.",
  "同一条光带从左向右经过每个字；只在图片 Alpha 内显示，花纹、象形图案和装饰也可参与。语言切换沿用时钟、色彩与速度，按字标实际宽度适配。": "The same light belt passes every word from the left to the right. It is shown only in the picture Alpha, and the pattern, pictograms and decorations can also be involved. Language switch to the clock, colour and speed and fit by the actual width of the font.",
