  "含未保存修改 · {0}": "Unsaved changes · {0}",
  "启动静态 HTTP 服务后打开 index.html，选择卡片与动作。shared/ 按内容摘要去重图像、Mask、几何与 GLSL；workshop.json 保留卡片引用与资源版本。project.cardworkshop 是可重新打开的源工程。每张卡的播放器读取共享文件；godot/ 内包含可运行的动态 SDK、Resource 库和预览场景。": "Starts the static HTTP service by opening index.html, and selects cards and actions. Shared/ by executive summary to re-introduce images, Mask, geometry and GLSL. Workshop.json preserves card references and resource versions. program.cardworkshop is a reopenable source project. Read shared files per card player. Godot/ contains runable dynamic SDK, Resources library and preview scenes.",
  "启动静态 HTTP 服务打开 index.html。素材与清晰度变体按内容摘要共享去重，运行时按缩放切换。此预设不含可编辑源工程，编辑器中的原工程不受影响。godot/ 包含动态 SDK。": "Starts the static HTTP service to open index.html. The material is shared with the clarity variable by weighting the content summary and running by scaling. This preset does not contain editable source projects, and the original project in the editor is not affected. godot/ contains dynamic SDK.",
