  "圆点与星芒": "Dots and Stars",
  "圆饼颜色对应骨骼。选点工具中点击选点，Shift / ⌘ / Ctrl 加选，拖动框选；点击选中圆饼扇区选择关联骨骼。外圈为笔刷范围，内圈为满强度区。锁定权重按网格记忆。": "Pie colors identify bones. Click vertices to select them, hold Shift or ⌘/Ctrl to add, and drag to box-select. Click a slice to select its bone. The brush reaches the outer ring and applies full strength inside the inner ring. Weight locks are saved per mesh.",
  "圈选人物区域": "Select Character Region",
