  "在 3D 中播放 / 暂停当前边框；2D 编辑画布显示静态素材": "Play / Pause the current border in 3D; 2D edit canvas to display static material",
  "在上方选择骨架工具并拖动。试姿势用于检查变形；记录模式在当前时间写关键帧；初始绑定模式修改关节结构。坐标为母版像素，子关节相对父节点。": "Select the skeleton tool above and drag it. The test position is used to check deformation. The recording mode is used to write key frames at the current time. The initial binding mode is used to modify the joint structure. The coordinates are master pixels, the sub-joint relative to the parent point.",
