  "拓扑变化超过误差阈值，已取消：": "The scaling-up exceeded the error threshold and was cancelled:",
  "拓扑变化超过误差阈值，已取消：{0}": "Upscale change above error threshold cancelled: {0}",
  "拓扑工具在初始姿势操作。普通网格移动点同步 UV；FFD 网格移动点保留 UV，调整初始形状。加点插值继承权重、逐骨骼绑定与全部 FFD 帧；删点同步重排动画索引，删除的局部细节随之移除。Shift 加选边的两个端点可翻转连边。边界点可删除并重新连接轮廓；超出误差阈值会取消整次操作。": "Edit topology in the rest pose. Moving ordinary mesh vertices updates their UVs. Moving FFD vertices changes the rest shape and keeps their UVs. New vertices inherit interpolated weights, bone bindings, and all FFD frames. Deleting vertices updates animation indices and removes their local detail. Shift-select both ends of an edge to flip it. You can delete and reconnect contour vertices within the error threshold.",
