  "操作说明": "Operational description",
  "操纵骨骼": "Manipulate the bones",
  "擦除": "Erase",
  "支持 JSON 3.8 / 4.0–4.3。替换骨架与人物动作，保留纯整卡动作、现有图片和 Mask。可加载本地图集并新增图片，或映射已有注册图片。FFD 在权重蒙皮前应用；附件切换保留为可见性轨道。不支持的内容会阻止应用。": "Import Spine JSON 3.8 or 4.0–4.3. Import replaces the rig and character actions while retaining card-wide actions, images, and masks. Load a local atlas to add images or map existing ones. FFD runs before skinning. Attachment changes become visibility tracks. Unsupported data blocks the import.",
  "支持本机字体与嵌入字体；素材包同时导出字标 PNG。": "Supports in-house fonts and embedded fonts. The package also exports the font PNG.",
  "支持连续的 1–16 节骨链。两节解析保留旧动作，多节 CCD 支持关节限制。目标可使用卡片坐标或独立骨骼的局部偏移；不拉伸骨长。": "Supports a continuous 1-16 skeletal chain. Two sections resolve to keep old actions, multiple CCDs to support joint limits. Targets can use card coordinates or local deviations of independent bones. Do not stretch bone lengths.",
  "支持闭合 SVG 路径、矩形、椭圆和多边形，保留曲线手柄。按嵌套奇偶规则识别实体和窗口；布尔结果会采样成折线，可撤销。默认按 SVG viewBox 居中适合画幅；先检查草稿，再应用。": "Supports closing SVG paths, rectangles, ellipses, and polygons, keeping curve handles. Identify entities and windows using the nested doll rule. The Boolean result is sampled into a fold and can be undone. Defaultly press SVG viewBox to fit the painting. Check the draft first, then apply.",
  "收取 result.json": "Collect result.json",
