  "此卡片已不在工坊中，请刷新最近列表": "This card is no longer in the workshop. Please update the latest list.",
  "此卡片已使用该版本": "This card has been used",
  "此卡的纹理、Mask、几何和 GLSL 路径见 manifest.json，指向工坊根目录 shared/。源工程为 ../../project.cardworkshop。启动根目录静态 HTTP 服务后打开 ../../index.html。PNG 可导入 Godot；完整godot/ 内包含可运行的动态 SDK、Resource 库和预览场景。": "The texture, Mask, Geometry and GLSL path to this card is shown in section.json, which points to the workshop root directory shareed/. The source project is …../project.cardworkshop. Starts the root directory static HTTP service and opens...././index.html. PNG can import Godot. Complete godot/ contains the active dynamic SDK, Resources library and preview scene.",
  "此参数不能改变边框图片；请在组件内编辑素材或效果": "This parameter cannot change the border picture. Please edit the material or effects within the component",
