  "此工坊操作仅作用于当前卡片": "This workshop operation only works on the current card",
  "此瘦客户端仅含 SDK 和远端加载示例，不含卡牌图片。运行后填入 HTTPS catalog.json 地址。Android 导出需启用 Internet 权限。完整素材上传 ../remote/，不要把本客户端当成远端内容上传。": "This thin client only contains examples of SDK and remote loading, without card pictures. After running, fill in the HTTPS catalog.json address. Android export requires Internet access../remote/ not upload the full material as a remote content.",
