  "每动作基础采样": "Sampling per action base",
  "每动作基础采样数": "Samples per action base",
  "每根骨骼都有自己的实心骨段，圆点为起点，小方块为末端；虚线表示父子层级。骨骼颜色与权重圆饼一致。初始工具编辑绑定姿势，动作工具与权重工具在当前姿势中操作；Esc 取消，一次拖动可一次撤销。": "A circle marks the root of each bone and a square marks its tip. Dashed lines show parent links. Bone colors match the weight chart. The bind tool edits the rest pose. Motion and weight tools edit the current pose. Press Esc to cancel. Each drag creates one undo step.",
  "每次提问需要 1–3 项": "1-3 items per question",
  "每种语言可导入不同 PNG：字形、花纹与图形都保留。统一扫光时钟；文字字段作为名称及回退。可移动、缩放或绑定 Slot。": "Each language can import different PNGs: fonts, wreaths and graphics are kept. A single light clock. A text field is used as a name and back. You can move, zoom or bind Slot.",
