  "输入 color、uv、time、mask，返回 vec4。mask.rg 为运动/框内外顶点权重；mask.ba 为发光/相位逐像素采样。角度可用 angle，强度可用 customStrength。": "Enter color, uv, time, mask, back vec4. mask.rg is the vertex weight of movement/box and outside. Mask.ba is sampled for light/phase by pixel. Angle is available and intensity is used for customStrength.",
  "输入 q、uv、time、bend，返回 vec3。人物仅在运动 Mask 内变形，并排除刚性保护；附加图层按代码变形。框体、背景、卡背保持刚性，整体旋转仍生效。": "Enter q, uv, time, bend to return vec3. The person is deformed only in motion Mask and excludes rigid protection. The additional layer is deformed by code. The frame, background, card back is rigid and the overall rotation is still valid.",
